// One draft for the whole app, alive until the tab closes
export function PriceDialog({ product }: { product: Product }) {
  const draft = useAppStore((s) => s.priceDraft);
  const setDraft = useAppStore((s) => s.setPriceDraft);

  return (
    <div role="dialog">
      <input value={draft} onChange={(e) => setDraft(e.target.value)} />
      <button onClick={() => savePrice(product.id, Number(draft))}>
        Save
      </button>
    </div>
  );
}

import { useState } from "react";

// Rendered as <PriceDialog key={product.id} product={product} />
export function PriceDialog({ product }: { product: Product }) {
  const [draft, setDraft] = useState(String(product.price));

  return (
    <div role="dialog">
      <input value={draft} onChange={(e) => setDraft(e.target.value)} />
      <button onClick={() => savePrice(product.id, Number(draft))}>
        Save
      </button>
    </div>
  );
}
